orders_timeline = (
    orders
    .sort_values(
        ["user_id", "order_number"]
    )
    .copy()
)

orders_timeline[
    "days_since_prior_order"
] = (
    orders_timeline[
        "days_since_prior_order"
    ]
    .fillna(0)
)

orders_timeline["shopping_day"] = (
    orders_timeline
    .groupby("user_id")
    ["days_since_prior_order"]
    .cumsum()
)


department_history = (
    department_orders[
        [
            "order_id",
            "department",
        ]
    ]
    .merge(
        orders_timeline[
            [
                "order_id",
                "user_id",
                "order_number",
                "shopping_day",
            ]
        ],
        on="order_id",
    )
    .sort_values(
        [
            "department",
            "user_id",
            "order_number",
        ]
    )
)


department_history[
    "department_cycle_days"
] = (
    department_history
    .groupby(
        [
            "department",
            "user_id",
        ]
    )["shopping_day"]
    .diff()
)


department_cycles = (
    department_history
    .dropna(
        subset=["department_cycle_days"]
    )
)


print(
    department_cycles[
        [
            "department",
            "user_id",
            "order_number",
            "department_cycle_days",
        ]
    ]
    .head()
)
